def _case(case_id, title, situation, info, question, options, correct, junior, incomplete, better, why, checks, data, lesson):
    feedback = tuple("This option is too general, unsupported or skips an important engineering check." for _ in range(len(options) - 1))
    return IndustryCase(case_id, title, situation, tuple(info), question, tuple(options), correct, junior, incomplete, better, why, feedback, tuple(checks), tuple(data), lesson)

