INDUSTRY_CASES_BY_ID = {x.case_id: x for x in INDUSTRY_CASES}

def validate_industry_catalog() -> None:
    if len(INDUSTRY_CASES_BY_ID) != len(INDUSTRY_CASES): raise ValueError("Duplicate industry case id")
    if len(PROFESSIONAL_TERMS_BY_ID) != len(PROFESSIONAL_TERMS): raise ValueError("Duplicate professional term id")
    for case in INDUSTRY_CASES:
        if case.correct_option not in case.options or not case.why_correct or not case.better_answer: raise ValueError(case.case_id)
        if len(case.other_options_feedback) != len(case.options)-1: raise ValueError(case.case_id)
    for term in PROFESSIONAL_TERMS:
        if not all((term.full_name, term.easy_explanation, term.where_used, term.example_sentence)): raise ValueError(term.term_id)
